mapper.select:
SELECT c.*, r.thumbnail AS thumbnail FROM comment c JOIN recipe r ON r.recipe_id = c.recipe_id WHERE c.member_id = #{member_id}
ORDER BY c.comment_id ASC
ORDER BY c.comment_id DESC
LIMIT #{size} OFFSET #{offset}

select count(c.comment_id) from comment c join member m on c.member_id = m.member_id left join board b on c.board_id = b.board_id left join recipe r on r.recipe_id = c.recipe_id where 1=1
and ( m.nickname like concat('%',#{keyword},'%') or b.title like concat('%',#{keyword},'%') )
and c.status = #{status}
